spec fn in_range_below(a: &[i64], lo: i64, hi: i64, n: usize) -> bool {
    forall|k: usize| k < n ==> lo <= #[trigger] a[k] && a[k] <= hi
}

spec fn all_in_range_ok(a: &[i64], lo: i64, hi: i64, r: bool) -> bool {
    r == in_range_below(a, lo, hi, a.len())
}

spec fn scan_inv(a: &[i64], lo: i64, hi: i64, i: usize, ok: bool) -> bool {
    i <= a.len() && ok == in_range_below(a, lo, hi, i)
}

#[effects(pure)]
#[uses(in_range_below, all_in_range_ok, scan_inv)]
fn all_in_range(a: &[i64], lo: i64, hi: i64) -> (r: bool)
    ensures all_in_range_ok(a, lo, hi, r),
{
    let mut i: usize = 0;
    let mut ok: bool = true;
    while i < a.len()
        invariant scan_inv(a, lo, hi, i, ok),
        decreases a.len() - i,
    {
        let x: i64 = a[i];
        ok = ok && lo <= x && x <= hi;
        i = i + 1;
    }
    ok
}

spec fn absent_from(a: &[i64], v: i64, n: usize) -> bool {
    forall|k: usize| n <= k && k < a.len() ==> #[trigger] a[k] != v
}

spec fn in_range_or_len(a: &[i64], r: usize) -> bool {
    r <= a.len()
}

spec fn last_found(a: &[i64], v: i64, r: usize) -> bool {
    r < a.len() ==> (a[r] == v && (forall|k: usize| r < k && k < a.len() ==> #[trigger] a[k] != v))
}

spec fn none_found(a: &[i64], v: i64, r: usize) -> bool {
    r == a.len() ==> (forall|k: usize| k < a.len() ==> #[trigger] a[k] != v)
}

#[effects(pure)]
#[uses(absent_from, in_range_or_len, last_found, none_found)]
fn find_last(a: &[i64], v: i64) -> (r: usize)
    ensures in_range_or_len(a, r), last_found(a, v, r), none_found(a, v, r),
{
    let mut i: usize = a.len();
    while i > 0 && a[i - 1] != v
        invariant i <= a.len(), absent_from(a, v, i),
        decreases i,
    {
        i = i - 1;
    }
    if i == 0 {
        a.len()
    } else {
        i - 1
    }
}

spec fn is_max3(a: i64, b: i64, c: i64, r: i64) -> bool {
    r >= a && r >= b && r >= c && (r == a || r == b || r == c)
}

#[effects(pure)]
#[uses(is_max3, num::is_max2)]
fn max3(a: i64, b: i64, c: i64) -> (r: i64)
    ensures is_max3(a, b, c, r),
{
    let m: i64 = num::max2(a, b);
    num::max2(m, c)
}

