spec fn reversed(dst: &[i64], src: &[i64]) -> bool {
    dst.len() == src.len() && (forall|k: usize| k < dst.len() ==> #[trigger] dst[k] == src[src.len() - 1 - k])
}

spec fn reversed_below(dst: &[i64], src: &[i64], n: usize) -> bool {
    forall|k: usize| k < n ==> #[trigger] dst[k] == src[src.len() - 1 - k]
}

#[effects(pure)]
#[uses(same_len, reversed, reversed_below)]
fn reverse_into(dst: &mut [i64], src: &[i64]) -> ()
    requires same_len(dst, src),
    ensures reversed(dst, src),
{
    let n: usize = dst.len();
    let mut k: usize = 0;
    while k < n
        invariant k <= n, n == dst.len(), dst.len() == src.len(), reversed_below(dst, src, k),
        decreases n - k,
    {
        dst[k] = src[n - 1 - k];
        k = k + 1;
    }
}

