spec fn digits_ok(n: u64, r: u64) -> bool {
    1 <= r && r <= n + 1 && ((r == 1) == (n < 10))
}

spec fn loop_inv(n: u64, m: u64, c: u64) -> bool {
    1 <= c && m <= n && c + m <= n + 1 && ((c == 1 && m == n) || (c > 1 && n >= 10))
}

#[effects(pure)]
#[uses(digits_ok, loop_inv)]
fn count_digits_iter(n: u64) -> (r: u64)
    ensures digits_ok(n, r),
{
    let mut m: u64 = n;
    let mut c: u64 = 1;
    while m >= 10
        invariant loop_inv(n, m, c),
        decreases m,
    {
        m = m / 10;
        c = c + 1;
    }
    c
}

