#[effects(pure)]
#[uses(range_ok, all_in_range, in_range_kept, clamped_below)]
fn clamp_all(a: &mut [i64], lo: i64, hi: i64) -> ()
    requires range_ok(lo, hi),
    ensures all_in_range(a, lo, hi), in_range_kept(a, old(a), lo, hi),
