        invariant k <= a.len(), lo <= hi, clamped_below(a, old(a), lo, hi, k),
        decreases a.len() - k,
    {
        let v: i64 = a[k];
        if v < lo {
            a[k] = lo;
        } else if v > hi {
            a[k] = hi;
        }
        k = k + 1;
    }
}

