#[effects(pure)]
#[uses(in_thousand, num::small, num::is_diff, ge_first, le_first, spread_range)]
fn spread(a: &[i64]) -> (r: i64)
    requires arr::nonempty(a), bounded_elems(a),
    ensures spread_range(r),
{
    let hi: i64 = max_of(a);
    let lo: i64 = min_of(a);
    num::sub_small(hi, lo)
