spec fn rotated_left(a: &[i64], b: &[i64]) -> bool {
    a.len() == b.len() && b.len() > 0
        && (forall|k: usize| k + 1 < a.len() ==> #[trigger] a[k] == b[k + 1])
        && a[a.len() - 1] == b[0]
}

spec fn shifted_below(a: &[i64], b: &[i64], n: usize) -> bool {
    forall|k: usize| k < n ==> #[trigger] a[k] == b[k + 1]
}

spec fn same_from(a: &[i64], b: &[i64], n: usize) -> bool {
    forall|k: usize| n <= k && k < a.len() ==> #[trigger] a[k] == b[k]
}

spec fn head_is(b: &[i64], v: i64) -> bool {
    b.len() > 0 && b[0] == v
}

#[effects(pure)]
#[uses(nonempty, rotated_left, shifted_below, same_from, head_is)]
fn rotate_left(a: &mut [i64]) -> ()
    requires nonempty(a),
    ensures rotated_left(a, old(a)),
{
    let first: i64 = a[0];
    let n: usize = a.len();
    let mut k: usize = 0;
    while k + 1 < n
        invariant k + 1 <= n, n == a.len(), a.len() == old(a).len(), head_is(old(a), first),
            shifted_below(a, old(a), k), same_from(a, old(a), k),
        decreases n - k,
    {
        a[k] = a[k + 1];
        k = k + 1;
    }
    a[n - 1] = first;
}

spec fn debit_ok(b: &[i64], i: usize, x: i64, r: bool) -> bool {
    r == (b[i] >= x)
}

spec fn credit_ok(b: &[i64], i: usize, x: i64, r: bool) -> bool {
    r == (b[i] <= 1000000000 - x)
}

spec fn transferred(a: &[i64], b: &[i64], i: usize, j: usize, x: i64, r: bool) -> bool {
    a.len() == b.len()
        && (r ==> a[i] == b[i] - x && a[j] == b[j] + x)
        && (!r ==> a[i] == b[i] && a[j] == b[j])
        && (forall|k: usize| k < a.len() && k != i && k != j ==> #[trigger] a[k] == b[k])
}

#[effects(pure)]
#[uses(acct, amount_ok, cap_ok, debited, moved, debit_ok)]
fn withdraw(a: &mut [i64], i: usize, x: i64) -> (r: bool)
    requires cap_ok(a), acct(a, i), amount_ok(x),
    ensures cap_ok(a), debited(a, old(a), i, x, r), debit_ok(old(a), i, x, r),
{
    if a[i] >= x {
        a[i] = a[i] - x;
        true
    } else {
        false
    }
}

#[effects(pure)]
#[uses(acct, amount_ok, cap_ok, credited, moved, credit_ok)]
fn deposit(a: &mut [i64], i: usize, x: i64) -> (r: bool)
    requires cap_ok(a), acct(a, i), amount_ok(x),
    ensures cap_ok(a), credited(a, old(a), i, x, r), credit_ok(old(a), i, x, r),
{
    if a[i] <= 1000000000 - x {
        a[i] = a[i] + x;
        true
    } else {
        false
    }
}

#[effects(pure)]
#[uses(acct, amount_ok, cap_ok, credited, debited, moved, debit_ok, credit_ok, transferred)]
fn transfer(a: &mut [i64], i: usize, j: usize, x: i64) -> (r: bool)
    requires cap_ok(a), acct(a, i), acct(a, j), amount_ok(x),
    ensures cap_ok(a), transferred(a, old(a), i, j, x, r),
{
    let mut ok: bool = false;
    if i != j && a[i] >= x && a[j] <= 1000000000 - x {
        let w: bool = withdraw(a, i, x);
        let d: bool = deposit(a, j, x);
        ok = w && d;
    }
    ok
}

spec fn paid_bound(a: &[i64], r: usize) -> bool {
    r <= a.len()
}

#[effects(pure)]
#[uses(acct, amount_ok, cap_ok, paid_bound)]
fn pay_all(a: &mut [i64], from: usize, x: i64) -> (r: usize)
    requires cap_ok(a), acct(a, from), amount_ok(x),
    ensures cap_ok(a), paid_bound(a, r),
{
    let mut paid: usize = 0;
    let mut k: usize = 0;
    while k < a.len()
        invariant k <= a.len(), paid <= k, from < a.len(), cap_ok(a),
        decreases a.len() - k,
    {
        if transfer(a, from, k, x) {
            paid = paid + 1;
        }
        k = k + 1;
    }
    paid
}

spec fn terminal_stays(s: i64, r: i64) -> bool {
    (s == 2 || s == 3) ==> r == s
}

#[effects(pure)]
#[uses(state_ok, terminal_stays)]
fn step(s: i64, ev: i64) -> (r: i64)
    requires state_ok(s),
    ensures state_ok(r), terminal_stays(s, r),
{
    if s == 0 {
        if ev == 1 {
            1
        } else {
            0
        }
    } else {
        if s == 1 {
            if ev == 2 {
                2
            } else {
                if ev < 0 {
                    3
                } else {
                    1
                }
            }
        } else {
            s
        }
    }
}

spec fn stays_terminal(s0: i64, r: i64) -> bool {
    (s0 == 2 || s0 == 3) ==> r == s0
}

#[effects(pure)]
#[uses(state_ok, stays_terminal)]
fn step(s: i64, ev: i64) -> (r: i64)
    requires state_ok(s),
    ensures state_ok(r), stays_terminal(s, r),
{
    if s == 0 {
        if ev == 1 {
            1
        } else {
            0
        }
    } else {
        if s == 1 {
            if ev == 2 {
                2
            } else {
                if ev < 0 {
                    3
                } else {
                    1
                }
            }
        } else {
            s
        }
    }
}

#[effects(pure)]
#[uses(state_ok, stays_terminal)]
fn run(events: &[i64], s0: i64) -> (r: i64)
    requires state_ok(s0),
    ensures state_ok(r), stays_terminal(s0, r),
{
    let mut s: i64 = s0;
    let mut k: usize = 0;
    while k < events.len()
        invariant k <= events.len(), state_ok(s), stays_terminal(s0, s),
        decreases events.len() - k,
    {
        s = step(s, events[k]);
        k = k + 1;
    }
    s
}

spec fn ends_swapped(a: &[i64], b: &[i64]) -> bool {
    a.len() == b.len() && b.len() > 0 && a[0] == b[b.len() - 1] && a[a.len() - 1] == b[0] && (forall|k: usize| k < a.len() && k != 0 && k != a.len() - 1 ==> #[trigger] a[k] == b[k])
}

#[effects(pure)]
#[uses(idx2, nonempty, swapped, ends_swapped)]
fn reverse_ends(a: &mut [i64]) -> ()
    requires nonempty(a),
    ensures ends_swapped(a, old(a)),
{
    let n: usize = a.len();
    swap(a, 0, n - 1);
}

spec fn step_ok(a: &[i64], b: &[i64], i: usize) -> bool {
    a.len() == b.len() && i < a.len()
        && (forall|k: usize| k < i ==> #[trigger] a[k] == b[k])
        && (forall|k: usize| i <= k && k < a.len() ==> a[i] <= #[trigger] a[k])
}

#[effects(pure)]
#[uses(arr::idx2, arr::swapped, from_ok, min_ok, step_ok)]
fn select_step(a: &mut [i64], i: usize) -> ()
    requires from_ok(a, i),
    ensures step_ok(a, old(a), i),
{
    let j: usize = min_index(a, i);
    arr::swap(a, i, j);
}

spec fn step_ok(a: &[i64], b: &[i64], i: usize) -> bool {
    a.len() == b.len() && i < a.len()
        && (forall|k: usize| k < i ==> #[trigger] a[k] == b[k])
        && (forall|m: usize| i <= m && m < a.len() ==> a[i] <= #[trigger] a[m])
}

#[effects(pure)]
#[uses(arr::idx2, arr::swapped, from_ok, min_ok, step_ok)]
fn select_step(a: &mut [i64], i: usize) -> ()
    requires from_ok(a, i),
    ensures step_ok(a, old(a), i),
{
    let j: usize = min_index(a, i);
    arr::swap(a, i, j);
}

spec fn is_abs_diff(a: i64, b: i64, r: i64) -> bool {
    r >= 0 && (r == a - b || r == b - a)
}

#[effects(pure)]
#[uses(small, is_abs_diff)]
fn abs_diff(a: i64, b: i64) -> (r: i64)
    requires small(a), small(b),
    ensures is_abs_diff(a, b, r),
{
    if a >= b {
        a - b
    } else {
        b - a
    }
}

spec fn elems_thousand(a: &[i64]) -> bool {
    forall|k: usize| k < a.len() ==> -1000 <= #[trigger] a[k] && a[k] <= 1000
}

spec fn gaps_upto(a: &[i64], n: usize, r: i64) -> bool {
    r >= 0 && (forall|i: usize| i < n && i + 1 < a.len() ==> (#[trigger] a[i]) - a[i + 1] <= r && a[i + 1] - a[i] <= r)
}

spec fn max_gap_ok(a: &[i64], r: i64) -> bool {
    r >= 0 && (forall|i: usize| i + 1 < a.len() ==> (#[trigger] a[i]) - a[i + 1] <= r && a[i + 1] - a[i] <= r)
}

#[effects(pure)]
#[uses(elems_thousand, gaps_upto, max_gap_ok, num::small, num::is_abs_diff)]
fn max_gap(a: &[i64]) -> (r: i64)
    requires elems_thousand(a),
    ensures max_gap_ok(a, r),
{
    if a.len() < 2 {
        0
    } else {
        let mut m: i64 = 0;
        let mut k: usize = 1;
        while k < a.len()
            invariant 1 <= k, k <= a.len(), gaps_upto(a, k - 1, m),
            decreases a.len() - k,
        {
            let d: i64 = num::abs_diff(a[k - 1], a[k]);
            if d > m {
                m = d;
            }
            k = k + 1;
        }
        m
    }
}

#[effects(pure)]
#[uses(ledger::acct, ledger::amount_ok, ledger::cap_ok, stats::at_most_len)]
fn deposit_all(a: &mut [i64], x: i64) -> (r: usize)
    requires ledger::cap_ok(a), ledger::amount_ok(x),
    ensures ledger::cap_ok(a), stats::at_most_len(a, r),
{
    let mut done: usize = 0;
    let mut k: usize = 0;
    while k < a.len()
        invariant k <= a.len(), done <= k, ledger::cap_ok(a), ledger::amount_ok(x),
        decreases a.len() - k,
    {
        if ledger::deposit(a, k, x) {
            done = done + 1;
        }
        k = k + 1;
    }
    done
}

spec fn same_len(a: &[i64], out: &[i64]) -> bool {
    a.len() == out.len()
}

spec fn first_ok(a: &[i64], out: &[i64]) -> bool {
    a.len() > 0 ==> out[0] == a[0]
}

spec fn steps_below(a: &[i64], out: &[i64], n: usize) -> bool {
    forall|k: usize| k + 1 < n ==> #[trigger] out[k + 1] == out[k] + a[k + 1]
}

spec fn steps_ok(a: &[i64], out: &[i64]) -> bool {
    forall|k: usize| k + 1 < a.len() ==> #[trigger] out[k + 1] == out[k] + a[k + 1]
}

#[effects(pure)]
#[uses(same_len, first_ok, steps_below, steps_ok, stats::bounded_elems, stats::sum_bound)]
fn prefix_sums(a: &[i64], out: &mut [i64]) -> ()
    requires same_len(a, out), stats::bounded_elems(a),
    ensures same_len(a, out), first_ok(a, out), steps_ok(a, out),
{
    if a.len() > 0 {
        out[0] = a[0];
        let mut s: i64 = a[0];
        let mut k: usize = 1;
        while k < a.len()
            invariant 1 <= k, k <= a.len(), out.len() == a.len(), out[0] == a[0],
                s == out[k - 1], stats::sum_bound(s, k), steps_below(a, out, k),
            decreases a.len() - k,
        {
            s = s + a[k];
            out[k] = s;
            k = k + 1;
        }
    }
}

spec fn a_ok(a: i64) -> bool {
    -1000000000 <= a && a <= 1000000000
}

spec fn b_ok(b: i64) -> bool {
    1 <= b && b <= 1000000000
}

spec fn floor_ok(a: i64, b: i64, r: i64) -> bool {
    r * b <= a && a < r * b + b
}

#[effects(pure)]
#[uses(a_ok, b_ok, floor_ok)]
fn div_floor(a: i64, b: i64) -> (r: i64)
    requires a_ok(a), b_ok(b),
    ensures floor_ok(a, b, r),
{
    let q: i64 = a / b;
    let m: i64 = a % b;
    if m < 0 {
        q - 1
    } else {
        q
    }
}

spec fn is_median3(a: i64, b: i64, c: i64, r: i64) -> bool {
    (r == a && ((b <= a && a <= c) || (c <= a && a <= b)))
    || (r == b && ((a <= b && b <= c) || (c <= b && b <= a)))
    || (r == c && ((a <= c && c <= b) || (b <= c && c <= a)))
}

#[effects(pure)]
#[uses(is_median3)]
fn median3(a: i64, b: i64, c: i64) -> (r: i64)
    ensures is_median3(a, b, c, r),
{
    if a <= b {
        if b <= c {
            b
        } else if a <= c {
            c
        } else {
            a
        }
    } else {
        if a <= c {
            a
        } else if b <= c {
            c
        } else {
            b
        }
    }
}

#[effects(pure)]
fn richest(a: &[i64]) -> (r: usize)
    requires arr::nonempty(a),
    ensures search::max_at(a, r),
{
    search::argmax(a)
}
